              <Regler label="Laufzeit" wert={laufzeit} min={20} max={40} step={1} einheit="Jahre" onChange={setLaufzeit} hinweis={`Üblich ${PACHT.laufzeit} Jahre + ${PACHT.verlaengerung}`} />
