/** Runde Achsenschritte (4–6 Linien) */
function schrittweite(max) {
  const roh = max / 5;
  const pot = Math.pow(10, Math.floor(Math.log10(roh)));
  const s = [1, 2, 2.5, 5, 10].map((f) => f * pot).find((v) => max / v <= 6) || pot * 10;
  const out = [];
  for (let v = 0; v <= max; v += s) out.push(v);
  return out;
}

