}
.ov-te-zeile {
  display: block;
  overflow: clip;
  /* Unterlängen (g, p, y) nicht abschneiden */
  padding-block: 0.1em;
  margin-block: -0.1em;
}
.ov-te-zeile-innen { display: block; }
@keyframes ov-te-wort { from { opacity: 0.001; transform: translate3d(0, 0.42em, 0); } to { opacity: 1; transform: none; } }
