    animation: ov-te-wort 560ms var(--ov-ease-out) both;
    animation-delay: calc(var(--ov-delay, 0ms) + var(--i, 0) * var(--ov-te-schritt, 40ms));
  }
  .ov-te-laden .ov-te-zeile-innen {
    animation: ov-te-zeile 640ms var(--ov-ease-out) both;
    animation-delay: calc(var(--ov-delay, 0ms) + var(--i, 0) * var(--ov-te-schritt, 90ms));
