  border-radius: inherit;
  overflow: hidden;
  pointer-events: none;
}
.ov-spot-licht::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  width: var(--ov-spot-groesse, 440px);
  height: var(--ov-spot-groesse, 440px);
  margin: calc(var(--ov-spot-groesse, 440px) / -2) 0 0 calc(var(--ov-spot-groesse, 440px) / -2);
  border-radius: 9999px;
