    VARIANTEN[variant] || VARIANTEN.primary,
    variant === "link" ? "gap-1.5 text-[15px]" : GROESSEN[size] || GROESSEN.md,
    block && "w-full",
    laedt && "pointer-events-none",
    magnetisch && "ov-magnet",
    className
  );

  const inhalt = (
    <>
