        <LoaderCircle aria-hidden="true" className="h-[1.1em] w-[1.1em] shrink-0 animate-ov-drehen" />
      ) : (
        Icon && <Icon aria-hidden="true" className="h-[1.1em] w-[1.1em] shrink-0" />
      )}
      <span>{children}</span>
      {pfeil && (
        <ArrowRight
          aria-hidden="true"
          className="h-[1.05em] w-[1.05em] shrink-0 transition-transform duration-300 ease-ov-out group-hover:translate-x-1 group-focus-visible:translate-x-1 motion-reduce:transition-none"
        />
      )}
    </>

